import React, { useEffect, useState } from 'react';
import { Navigate, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth, useLang } from '../App';

const emptyQuestion = {
  question_rw: '',
  question_en: '',
  option_a_rw: '',
  option_b_rw: '',
  option_c_rw: '',
  option_d_rw: '',
  option_a_en: '',
  option_b_en: '',
  option_c_en: '',
  option_d_en: '',
  correct_answer: 'a',
  category: 'general'
};

export default function AdminDashboardPage() {
  const { user, logout } = useAuth();
  const { lang, setLang } = useLang();
  const navigate = useNavigate();
  const token = localStorage.getItem('rnp_token');
  const headers = { Authorization: `Bearer ${token}` };

  const [tab, setTab] = useState('overview');
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState('');
  const [overview, setOverview] = useState(null);
  const [users, setUsers] = useState([]);
  const [questions, setQuestions] = useState([]);
  const [exams, setExams] = useState([]);
  const [system, setSystem] = useState(null);
  const [selectedUser, setSelectedUser] = useState(null);
  const [userExams, setUserExams] = useState([]);
  const [questionForm, setQuestionForm] = useState(emptyQuestion);
  const [editingQuestion, setEditingQuestion] = useState(null);

  const t = lang === 'rw' ? rw : en;

  const api = (method, url, data) => axios({ method, url, data, headers });

  const loadOverview = async () => {
    const res = await api('get', '/api/admin/overview');
    setOverview(res.data);
  };

  const loadUsers = async () => {
    const res = await api('get', '/api/admin/users');
    setUsers(res.data);
  };

  const loadQuestions = async () => {
    const res = await api('get', '/api/admin/questions');
    setQuestions(res.data);
  };

  const loadExams = async () => {
    const res = await api('get', '/api/admin/exams');
    setExams(res.data);
  };

  const loadSystem = async () => {
    const res = await api('get', '/api/admin/system');
    setSystem(res.data);
  };

  const loadAll = async () => {
    setLoading(true);
    try {
      await Promise.all([loadOverview(), loadUsers(), loadQuestions(), loadExams(), loadSystem()]);
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to load admin data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAll();
  }, []);

  const loadUserExams = async (userId) => {
    const res = await api('get', `/api/admin/users/${userId}/exams`);
    setUserExams(res.data);
    setSelectedUser(userId);
  };

  const qChange = (key) => (e) => setQuestionForm(f => ({ ...f, [key]: e.target.value }));

  const resetQuestionForm = () => {
    setQuestionForm(emptyQuestion);
    setEditingQuestion(null);
  };

  const saveQuestion = async (e) => {
    e.preventDefault();
    try {
      if (!questionForm.question_rw || !questionForm.option_a_rw || !questionForm.option_b_rw || !questionForm.option_c_rw || !questionForm.option_d_rw) {
        setMessage(lang === 'rw' ? 'Kinyarwanda question and all options are required' : 'Kinyarwanda question and all options are required');
        return;
      }
      if (editingQuestion) {
        await api('put', `/api/admin/questions/${editingQuestion}`, questionForm);
        setMessage(lang === 'rw' ? 'Ikibazo cyavuguruwe' : 'Question updated');
      } else {
        await api('post', '/api/admin/questions', questionForm);
        setMessage(lang === 'rw' ? 'Ikibazo cyiyongewemo' : 'Question added');
      }
      resetQuestionForm();
      await loadQuestions();
      await loadOverview();
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to save question');
    }
  };

  const editQuestion = (q) => {
    setQuestionForm(q);
    setEditingQuestion(q.id);
    setTab('questions');
  };

  const deleteQuestion = async (id) => {
    if (!window.confirm(lang === 'rw' ? 'Gusiba iki kibazo?' : 'Delete this question?')) return;
    try {
      await api('delete', `/api/admin/questions/${id}`);
      await loadQuestions();
      await loadOverview();
      setMessage(lang === 'rw' ? 'Ikibazo cyasibwe' : 'Question deleted');
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to delete question');
    }
  };

  const resetUserPassword = async (u) => {
    const password = window.prompt(lang === 'rw' ? 'Shyiramo ijambobanga rishya:' : 'Enter new password:');
    if (!password) return;
    try {
      await api('post', `/api/admin/users/${u.id}/reset-password`, { password });
      setMessage(`${u.email}: ${lang === 'rw' ? 'ijambobanga ryahinduwe' : 'password reset'}`);
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to reset password');
    }
  };

  const updateUser = async (u, role) => {
    if (!window.confirm(lang === 'rw' ? 'Guhindura uruhare rwuyu mukoresha?' : 'Change this user role?')) return;
    try {
      await api('put', `/api/admin/users/${u.id}`, { ...u, role });
      await loadUsers();
      setMessage(lang === 'rw' ? 'Uruhare rwahinduwe' : 'Role updated');
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to update role');
    }
  };

  const deleteUser = async (u) => {
    if (!window.confirm(lang === 'rw' ? 'Gusiba uyu mukoresha n\'ibizamini bye?' : 'Delete this user and their exams?')) return;
    try {
      await api('delete', `/api/admin/users/${u.id}`);
      await loadUsers();
      await loadOverview();
      setMessage(lang === 'rw' ? 'Umwirondoro wasibwe' : 'User deleted');
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to delete user');
    }
  };

  const deleteExam = async (id) => {
    if (!window.confirm(lang === 'rw' ? 'Gusiba iki kizamini?' : 'Delete this exam record?')) return;
    try {
      await api('delete', `/api/admin/exams/${id}`);
      await loadExams();
      await loadOverview();
      setMessage(lang === 'rw' ? 'Ikizamini cyasibwe' : 'Exam deleted');
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to delete exam');
    }
  };

  const clearExams = async () => {
    if (!window.confirm(lang === 'rw' ? 'Gusiba ibizamini byose?' : 'Clear all exam records?')) return;
    try {
      await api('post', '/api/admin/system/clear-exams');
      await loadAll();
      setMessage(lang === 'rw' ? 'Ibizami byose byasibwe' : 'Exam records cleared');
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to clear exams');
    }
  };

  const clearUsers = async () => {
    if (!window.confirm(lang === 'rw' ? 'Gusiba abakiriya bose n\'ibizamini byabo?' : 'Clear all client users and exams?')) return;
    try {
      await api('post', '/api/admin/system/clear-users');
      await loadAll();
      setMessage(lang === 'rw' ? 'Abakiriya bose basibwe' : 'Client users cleared');
    } catch (err) {
      setMessage(err.response?.data?.message || 'Failed to clear users');
    }
  };

  if (user?.role !== 'admin') return <Navigate to="/dashboard" replace />;

  const fmtDate = d => d ? new Date(d).toLocaleString() : '-';
  const fmtScore = n => Number(n || 0).toFixed(2);

  const tabs = [
    ['overview', t.overview],
    ['users', t.users],
    ['questions', t.questions],
    ['exams', t.exams],
    ['system', t.system]
  ];

  return (
    <div style={styles.page}>
      <div style={styles.nav}>
        <div style={styles.navLeft}>
          <span style={styles.navIcon}>🦅</span>
          <span style={styles.navTitle}>HAVANA SHELF DEPARTMENT - ADMIN</span>
        </div>
        <div style={styles.navRight}>
          <div className="lang-toggle">
            <button className={`lang-btn ${lang === 'rw' ? 'active' : ''}`} onClick={() => setLang('rw')}>RW</button>
            <button className={`lang-btn ${lang === 'en' ? 'active' : ''}`} onClick={() => setLang('en')}>EN</button>
          </div>
          <button onClick={logout} style={styles.logoutBtn}>{t.logout}</button>
        </div>
      </div>

      <div style={styles.container}>
        <div style={styles.headerRow}>
          <div>
            <h1 style={styles.pageTitle}>{t.title}</h1>
            <p style={styles.sub}>{t.sub}</p>
          </div>
          <button className="btn-orange" onClick={() => navigate('/dashboard')}>{t.clientDashboard}</button>
        </div>

        {message && <div style={styles.message}>{message}</div>}

        <div style={styles.tabs}>
          {tabs.map(([key, label]) => (
            <button
              key={key}
              className={tab === key ? 'active' : ''}
              style={{...styles.tab, background: tab === key ? '#2563eb' : 'white', color: tab === key ? 'white' : '#1e293b'}}
              onClick={() => setTab(key)}
            >
              {label}
            </button>
          ))}
        </div>

        {loading ? (
          <div style={styles.loading}>{lang === 'rw' ? 'Gutegura amakuru...' : 'Loading admin data...'}</div>
        ) : (
          <div>
            {tab === 'overview' && overview && (
              <div>
                <div style={styles.cards}>
                  <Card label={t.questions} value={overview.questions} />
                  <Card label={t.users} value={overview.users} />
                  <Card label={t.clients} value={overview.userCount} />
                  <Card label={t.admins} value={overview.adminCount} />
                  <Card label={t.exams} value={overview.exams} />
                  <Card label={t.passed} value={`${overview.passed}/${overview.exams}`} />
                  <Card label={t.passRate} value={`${overview.passRate}%`} />
                  <Card label={t.avgScore} value={fmtScore(overview.avgScore)} />
                </div>

                <div style={styles.grid}>
                  <div style={styles.card}>
                    <h3 style={styles.cardTitle}>{t.recentExams}</h3>
                    {overview.recentExams.length === 0 ? <p style={styles.empty}>{t.noData}</p> : (
                      <table style={styles.table}>
                        <thead>
                          <tr>
                            <th style={styles.th}>{t.user}</th>
                            <th style={styles.th}>{t.score}</th>
                            <th style={styles.th}>{t.status}</th>
                            <th style={styles.th}>{t.date}</th>
                          </tr>
                        </thead>
                        <tbody>
                          {overview.recentExams.map(ex => (
                            <tr key={ex.id}>
                              <td style={styles.td}>{ex.names}<br /><span style={styles.muted}>{ex.email}</span></td>
                              <td style={styles.td}>{ex.score}/{ex.total_questions}</td>
                              <td style={styles.td}><span className={ex.passed ? 'badge-pass' : 'badge-fail'}>{ex.passed ? t.pass : t.fail}</span></td>
                              <td style={styles.td}>{fmtDate(ex.start_time)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    )}
                  </div>
                </div>
              </div>
            )}

            {tab === 'users' && (
              <div style={styles.card}>
                <h3 style={styles.cardTitle}>{t.clients}</h3>
                <div style={styles.tableWrap}>
                  <table style={styles.table}>
                    <thead>
                      <tr>
                        <th style={styles.th}>{t.name}</th>
                        <th style={styles.th}>{t.email}</th>
                        <th style={styles.th}>{t.phone}</th>
                        <th style={styles.th}>{t.examTaken}</th>
                        <th style={styles.th}>{t.passed}</th>
                        <th style={styles.th}>{t.failed}</th>
                        <th style={styles.th}>{t.avg}</th>
                        <th style={styles.th}>{t.best}</th>
                        <th style={styles.th}>{t.role}</th>
                        <th style={styles.th}>{t.actions}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {users.map(u => (
                        <tr key={u.id}>
                          <td style={styles.td}>{u.names}<br /><span style={styles.muted}>{fmtDate(u.created_at)}</span></td>
                          <td style={styles.td}>{u.email}</td>
                          <td style={styles.td}>{u.phone || '-'}</td>
                          <td style={styles.td}>{u.exams_taken}</td>
                          <td style={styles.td}>{u.passed_exams}</td>
                          <td style={styles.td}>{u.failed_exams}</td>
                          <td style={styles.td}>{fmtScore(u.avg_score)}</td>
                          <td style={styles.td}>{u.best_score}</td>
                          <td style={styles.td}>
                            <select
                              value={u.role}
                              onChange={(e) => updateUser(u, e.target.value)}
                              style={styles.select}
                            >
                              <option value="user">{t.client}</option>
                              <option value="admin">{t.admin}</option>
                            </select>
                          </td>
                          <td style={styles.td}>
                            <div style={styles.actions}>
                              <button className="btn-sm" onClick={() => loadUserExams(u.id)}>{t.history}</button>
                              <button className="btn-sm outline" onClick={() => resetUserPassword(u)}>{t.resetPassword}</button>
                              <button className="btn-sm danger" onClick={() => deleteUser(u)}>{t.delete}</button>
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {tab === 'users' && selectedUser && (
              <div style={{...styles.card, marginTop: 16}}>
                <h3 style={styles.cardTitle}>{t.userExamHistory}</h3>
                {userExams.length === 0 ? <p style={styles.empty}>{t.noData}</p> : (
                  <table style={styles.table}>
                    <thead>
                      <tr>
                        <th style={styles.th}>#</th>
                        <th style={styles.th}>{t.date}</th>
                        <th style={styles.th}>{t.score}</th>
                        <th style={styles.th}>{t.status}</th>
                        <th style={styles.th}>{t.answers}</th>
                      </tr>
                    </thead>
                    <tbody>
                      {userExams.map((ex, i) => (
                        <tr key={ex.id}>
                          <td style={styles.td}>{i + 1}</td>
                          <td style={styles.td}>{fmtDate(ex.start_time)}</td>
                          <td style={styles.td}>{ex.score}/{ex.total_questions}</td>
                          <td style={styles.td}><span className={ex.passed ? 'badge-pass' : 'badge-fail'}>{ex.passed ? t.pass : t.fail}</span></td>
                          <td style={styles.td}><pre style={styles.pre}>{ex.answers}</pre></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>
            )}

            {tab === 'questions' && (
              <div>
                <div style={styles.grid}>
                  <div style={styles.card}>
                    <h3 style={styles.cardTitle}>{editingQuestion ? t.editQuestion : t.addQuestion}</h3>
                    <form onSubmit={saveQuestion} style={styles.form}>
                      <div style={styles.grid2}>
                        <Input label={t.questionRw} value={questionForm.question_rw} onChange={qChange('question_rw')} required />
                        <Input label={t.questionEn} value={questionForm.question_en} onChange={qChange('question_en')} />
                      </div>
                      <div style={styles.grid2}>
                        <Input label="A RW" value={questionForm.option_a_rw} onChange={qChange('option_a_rw')} required />
                        <Input label="B RW" value={questionForm.option_b_rw} onChange={qChange('option_b_rw')} required />
                        <Input label="C RW" value={questionForm.option_c_rw} onChange={qChange('option_c_rw')} required />
                        <Input label="D RW" value={questionForm.option_d_rw} onChange={qChange('option_d_rw')} required />
                      </div>
                      <div style={styles.grid2}>
                        <Input label="A EN" value={questionForm.option_a_en} onChange={qChange('option_a_en')} />
                        <Input label="B EN" value={questionForm.option_b_en} onChange={qChange('option_b_en')} />
                        <Input label="C EN" value={questionForm.option_c_en} onChange={qChange('option_c_en')} />
                        <Input label="D EN" value={questionForm.option_d_en} onChange={qChange('option_d_en')} />
                      </div>
                      <div style={styles.grid2}>
                        <div className="form-group">
                          <label>{t.correct}</label>
                          <select value={questionForm.correct_answer} onChange={qChange('correct_answer')} style={styles.selectFull}>
                            <option value="a">A</option>
                            <option value="b">B</option>
                            <option value="c">C</option>
                            <option value="d">D</option>
                          </select>
                        </div>
                        <Input label={t.category} value={questionForm.category} onChange={qChange('category')} />
                      </div>
                      <div style={styles.actions}>
                        <button type="submit" className="btn-blue">{editingQuestion ? t.save : t.add}</button>
                        {editingQuestion && <button type="button" className="btn-outline" onClick={resetQuestionForm}>{t.cancel}</button>}
                      </div>
                    </form>
                  </div>

                  <div style={styles.card}>
                    <h3 style={styles.cardTitle}>{t.questions}</h3>
                    <div style={styles.tableWrap}>
                      <table style={styles.table}>
                        <thead>
                          <tr>
                            <th style={styles.th}>ID</th>
                            <th style={styles.th}>{t.category}</th>
                            <th style={styles.th}>{t.correct}</th>
                            <th style={styles.th}>{t.question}</th>
                            <th style={styles.th}>{t.actions}</th>
                          </tr>
                        </thead>
                        <tbody>
                          {questions.map(q => (
                            <tr key={q.id}>
                              <td style={styles.td}>{q.id}</td>
                              <td style={styles.td}>{q.category}</td>
                              <td style={styles.td}>{q.correct_answer.toUpperCase()}</td>
                              <td style={styles.td}>{q.question_rw}<br /><span style={styles.muted}>{q.question_en}</span></td>
                              <td style={styles.td}>
                                <div style={styles.actions}>
                                  <button className="btn-sm" onClick={() => editQuestion(q)}>{t.edit}</button>
                                  <button className="btn-sm danger" onClick={() => deleteQuestion(q.id)}>{t.delete}</button>
                                </div>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {tab === 'exams' && (
              <div style={styles.card}>
                <h3 style={styles.cardTitle}>{t.examRecords}</h3>
                {exams.length === 0 ? <p style={styles.empty}>{t.noData}</p> : (
                  <div style={styles.tableWrap}>
                    <table style={styles.table}>
                      <thead>
                        <tr>
                          <th style={styles.th}>ID</th>
                          <th style={styles.th}>{t.user}</th>
                          <th style={styles.th}>{t.date}</th>
                          <th style={styles.th}>{t.score}</th>
                          <th style={styles.th}>{t.status}</th>
                          <th style={styles.th}>{t.answers}</th>
                          <th style={styles.th}>{t.actions}</th>
                        </tr>
                      </thead>
                      <tbody>
                        {exams.map(ex => (
                          <tr key={ex.id}>
                            <td style={styles.td}>{ex.id}</td>
                            <td style={styles.td}>{ex.names}<br /><span style={styles.muted}>{ex.email}</span></td>
                            <td style={styles.td}>{fmtDate(ex.start_time)}</td>
                            <td style={styles.td}>{ex.score}/{ex.total_questions}</td>
                            <td style={styles.td}><span className={ex.passed ? 'badge-pass' : 'badge-fail'}>{ex.passed ? t.pass : t.fail}</span></td>
                            <td style={styles.td}><pre style={styles.pre}>{ex.answers}</pre></td>
                            <td style={styles.td}><button className="btn-sm danger" onClick={() => deleteExam(ex.id)}>{t.delete}</button></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}

            {tab === 'system' && system && (
              <div>
                <div style={styles.grid}>
                  <div style={styles.card}>
                    <h3 style={styles.cardTitle}>{t.systemInfo}</h3>
                    <Info label="Node" value={system.nodeVersion} />
                    <Info label="Platform" value={system.platform} />
                    <Info label="Uptime" value={`${system.uptimeSeconds}s`} />
                    <Info label="Database" value={system.databasePath} />
                  </div>
                  <div style={styles.card}>
                    <h3 style={styles.cardTitle}>{t.tableCounts}</h3>
                    {Object.keys(system.counts).map(key => (
                      <Info key={key} label={key} value={system.counts[key]} />
                    ))}
                  </div>
                </div>
                <div style={{...styles.card, marginTop:16}}>
                  <h3 style={styles.cardTitle}>{t.dangerZone}</h3>
                  <p style={styles.warning}>{t.dangerText}</p>
                  <div style={styles.actions}>
                    <button className="btn-orange" onClick={clearExams}>{t.clearExams}</button>
                    <button className="btn-orange" onClick={clearUsers}>{t.clearUsers}</button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function Card({ label, value }) {
  return (
    <div style={styles.statCard}>
      <div style={styles.statLabel}>{label}</div>
      <div style={styles.statValue}>{value}</div>
    </div>
  );
}

function Input({ label, value, onChange, required }) {
  return (
    <div className="form-group">
      <label>{label}</label>
      <input value={value} onChange={onChange} required={required} />
    </div>
  );
}

function Info({ label, value }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', gap: 16, padding: '8px 0', borderBottom: '1px solid #e2e8f0' }}>
      <span style={styles.muted}>{label}</span>
      <strong style={{ color: '#1e293b' }}>{value}</strong>
    </div>
  );
}

